import Foundation
struct StrategyBar {var t:Int64;var o:Double;var h:Double;var l:Double;var c:Double;var v:Double}
enum StrategyError:LocalizedError {case invalid(String);var errorDescription:String?{switch self{case .invalid(let s):return s}}}
struct EquityPoint:Codable {let bar_timestamp_ms:Int64;let equity:Double}
struct StrategyFill:Codable {let timestamp_ms:Int64;let side:String;let price:Double;let quantity:Double;let fee:Double}
final class StrategyCore {
 var curve:[EquityPoint]=[],fillRecords:[StrategyFill]=[],curveLimit=50000,wins=0,totalFees=0.0,grossWins=0.0,grossLosses=0.0,entryCost=0.0,priceCurrency="INPUT_PRICE_CURRENCY"
 var winRate:Double?{sells==0 ? nil:Double(wins)/Double(sells)}
 var profitFactor:Double?{grossLosses==0 ? nil:grossWins/grossLosses}
 func recordCurve(_ t:Int64){let p=EquityPoint(bar_timestamp_ms:t,equity:equity);if curve.last?.bar_timestamp_ms==t{curve[curve.count-1]=p}else{curve.append(p)};if curve.count>curveLimit{curve.removeFirst()}}

 let start:Double,fee:Double,slip:Double
 var cash:Double,qty=0.0,entry=0.0,lastPrice=0.0,ema9=0.0,ema21=0.0,peak:Double,maxDD=0.0
 var bars=0,buys=0,sells=0,pending=0,halted=false,reason="준비",lastBar=Int64.min,fills:[String]=[]
 init(_ equity:Double,_ feeBps:Double,_ slipBps:Double)throws{guard equity.isFinite,equity>0,feeBps.isFinite,(0...100).contains(feeBps),slipBps.isFinite,(0...100).contains(slipBps)else{throw StrategyError.invalid("자본 양수, 비용 0~100 bps")};start=equity;cash=equity;peak=equity;fee=feeBps/10000;slip=slipBps/10000}
 var equity:Double{cash+qty*lastPrice}
 func mark(_ price:Double){lastPrice=price;let e=equity;peak=max(peak,e);maxDD=max(maxDD,100*(peak-e)/peak);if e<=start*0.95{halted=true;reason="시작 자본 대비 5% 손실: 신규 진입 중지"}}
 func fill(_ t:Int64,_ side:String,_ p:Double,_ q:Double){fills.append(ISO8601DateFormatter().string(from:Date(timeIntervalSince1970:Double(t)/1000))+" "+side+String(format:" %.8f @ %.4f",q,p));if fills.count>5000{fills.removeFirst()};let f=p*q*fee;totalFees+=f;fillRecords.append(StrategyFill(timestamp_ms:t,side:side,price:p,quantity:q,fee:f));if fillRecords.count>5000{fillRecords.removeFirst()}}
 func open(_ t:Int64,_ price:Double){mark(price);let action=pending;pending=0;if action<0 && qty>0{sell(t,price,"EMA 매도")}else if action>0 && qty==0 && !halted{let p=price*(1+slip),budget=cash*0.1;qty=budget/(p*(1+fee));entry=p;entryCost=budget;cash-=budget;buys+=1;fill(t,"모의 매수",p,qty)};mark(price)}
 func sell(_ t:Int64,_ price:Double,_ why:String){guard qty>0 else{return};let p=price*(1-slip);fill(t,"모의 매도 · "+why,p,qty);let proceeds=qty*p*(1-fee),pnl=proceeds-entryCost;if pnl>0{wins+=1;grossWins+=pnl}else{grossLosses-=pnl};cash+=proceeds;qty=0;sells+=1;mark(price)}
 func observe(_ t:Int64,_ price:Double){guard price.isFinite,price>0 else{return};if qty>0{if price<=entry*0.985{sell(t,price,"관측 손절")}else if price>=entry*1.03{sell(t,price,"관측 익절")}};mark(price)}
 func close(_ b:StrategyBar)throws{guard b.t>lastBar else{throw StrategyError.invalid("중복/역순 봉")};lastBar=b.t;let a=ema9,z=ema21;ema9=bars==0 ? b.c:0.2*b.c+0.8*ema9;ema21=bars==0 ? b.c:2.0/22*b.c+20.0/22*ema21;bars+=1;mark(b.c);if bars>=30{if ema9>ema21 && a<=z && qty==0 && !halted{pending=1}else if ema9<ema21 && a>=z && qty>0{pending = -1}};recordCurve(b.t);if !halted{reason="EMA9/21 · \(bars)봉 · 다음 관측 가격 체결 대기"}}
 func process(_ b:StrategyBar)throws{open(b.t,b.o);if qty>0{if b.o<=entry*0.985{sell(b.t,b.o,"갭 손절")}else if b.l<=entry*0.985{sell(b.t,entry*0.985,"손절 우선")}else if b.h>=entry*1.03{sell(b.t,max(b.o,entry*1.03),"익절")}};try close(b)}
 static func syntheticRows()->[StrategyBar]{(0..<32).map{i in StrategyBar(t:1767225600000+Int64(i)*60000,o:i==31 ? 110:100,h:i>=30 ? 110:100,l:i==31 ? 110:100,c:i>=30 ? 110:100,v:0)}}
 static func backtest(_ rows:[StrategyBar],_ equity:Double,_ fee:Double,_ slip:Double)throws->StrategyCore{let e=try StrategyCore(equity,fee,slip);for b in rows{if Task.isCancelled{throw StrategyError.invalid("취소됨")};try e.process(b)};if let last=rows.last{e.sell(last.t,last.c,"데이터 종료")};e.pending=0;if let last=rows.last{e.recordCurve(last.t)};return e}
 static func csv(_ raw:String)throws->[StrategyBar]{let lines=raw.replacingOccurrences(of:"\u{feff}",with:"").replacingOccurrences(of:"\r",with:"").components(separatedBy:"\n");guard lines.count>=3,lines.count<=50002 else{throw StrategyError.invalid("CSV 2~50000봉 필요")};let head=lines[0].components(separatedBy:",").map{$0.trimmingCharacters(in:.whitespaces).replacingOccurrences(of:"\"",with:"").lowercased()};let keys=["timestamp","open","high","low","close","volume"];guard keys.allSatisfy({head.contains($0)})else{throw StrategyError.invalid("timestamp,open,high,low,close,volume 필요")};let indices=keys.map{head.firstIndex(of:$0)!};let date=ISO8601DateFormatter(),fractional=ISO8601DateFormatter();fractional.formatOptions=[.withInternetDateTime,.withFractionalSeconds];var out:[StrategyBar]=[];var prev=Int64.min
 for (i,line) in lines.dropFirst().enumerated(){if line.trimmingCharacters(in:.whitespaces).isEmpty{continue};let f=line.components(separatedBy:",").map{$0.trimmingCharacters(in:.whitespaces).replacingOccurrences(of:"\"",with:"")};guard indices.max()!<f.count,let d=fractional.date(from:f[indices[0]]) ?? date.date(from:f[indices[0]])else{throw StrategyError.invalid("CSV \(i+2)행: 시간/열 오류")};let values=indices.dropFirst().compactMap{Double(f[$0])};guard values.count==5,values.allSatisfy({$0.isFinite})else{throw StrategyError.invalid("CSV 숫자 오류")};let t=Int64((d.timeIntervalSince1970*1000).rounded()),o=values[0],h=values[1],l=values[2],c=values[3],v=values[4];guard t>prev,min(o,h,l,c)>0,v>=0,l<=min(o,c),h>=max(o,c),h>=l else{throw StrategyError.invalid("CSV \(i+2)행: 순서/OHLCV 오류")};prev=t;out.append(StrategyBar(t:t,o:o,h:h,l:l,c:c,v:v))};guard (2...50000).contains(out.count)else{throw StrategyError.invalid("CSV 봉 수 오류")};return out}
 var summary:String{String(format:"모바일 EMA 현물 모의 전략 (기존 v1.6과 별도)\n가격 통화 기준 자본 %.2f → 평가 %.2f\n수익률 %+.4f%% · 최대 낙폭 %.4f%%\n매수 %d / 매도 %d · 보유 %.8f\n",start,equity,(equity/start-1)*100,maxDD,buys,sells,qty)+reason+String(format:"\n자본 10%% 진입 · 손절 1.5%% · 익절 3%%\n수수료 %.2f bps · 슬리피지 %.2f bps\n",fee*10000,slip*10000)+fills.suffix(8).joined(separator:"\n")}
 func report()->Data{let j:[String:Any]=["mode":"MOBILE_PAPER_EMA_SPOT_V2","report_schema_version":2,"full_v1_1_implemented":false,"closed_trades":sells,"ending_equity":equity,"return_pct":(equity/start-1)*100,"max_drawdown_pct":maxDD,"position_quantity":qty,"halted":halted,"fills":fills,"fill_records":fillRecords.map{["timestamp_ms":$0.timestamp_ms,"side":$0.side,"price":$0.price,"quantity":$0.quantity,"fee":$0.fee] as [String:Any]},"equity_curve":curve.map{["bar_timestamp_ms":$0.bar_timestamp_ms,"equity":$0.equity] as [String:Any]},"win_rate":winRate.map{$0 as Any} ?? NSNull(),"profit_factor_net":profitFactor.map{$0 as Any} ?? NSNull(),"total_fees":totalFees,"price_currency":priceCurrency,"curve_time_basis":"input_or_observed_bar_timestamp","curve_truncated":bars>curve.count,"fill_records_truncated":buys+sells>fillRecords.count];return (try? JSONSerialization.data(withJSONObject:j,options:[.prettyPrinted,.sortedKeys])) ?? Data()}

}
final class LivePaper {
 let started=Date()
 let symbol:String,engine:StrategyCore
 var bar:StrategyBar?,running=true,discard=true,event=Int64.min,received=Int64.min
 init(_ symbol:String,_ equity:Double,_ fee:Double,_ slip:Double)throws{self.symbol=symbol;engine=try StrategyCore(equity,fee,slip);engine.curveLimit=3600;engine.priceCurrency="KRW"}
 func pause(_ why:String){running=false;engine.reason=why+" · 잔여 모의 보유 유지";engine.pending=0}
 func tick(_ t:Int64,_ receive:Int64,_ now:Int64,_ price:Double){guard running else{return};guard MarketMath.valid(price,event:Date(timeIntervalSince1970:Double(t)/1000),received:Date(timeIntervalSince1970:Double(receive)/1000),now:Date(timeIntervalSince1970:Double(now)/1000),maxAge:15)else{pause("지연 시세로 일시 정지");return};if t<event || receive<=received{return};if received != Int64.min && receive-received>15000{pause("수신 공백으로 일시 정지");return};event=t;received=receive;let bucket=t/60000*60000;guard var b=bar else{bar=StrategyBar(t:bucket,o:price,h:price,l:price,c:price,v:0);return};if bucket<b.t{return};if bucket>b.t{guard bucket-b.t==60000 else{pause("관측 봉 공백으로 일시 정지");return};if !discard{do{try engine.close(b)}catch{pause("봉 순서 오류");return}};discard=false;engine.open(t,price);b=StrategyBar(t:bucket,o:price,h:price,l:price,c:price,v:0)}else{b.h=max(b.h,price);b.l=min(b.l,price);b.c=price};bar=b;engine.observe(t,price)}
}
